<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import type { Dataset } from '../lib/timetable'
import type { Change } from '../lib/insights'
const props = defineProps<{data:Dataset}>()
interface Report {schema_version:number;baseline:boolean;current:{sha:string;imported_at:string};previous:{sha:string;imported_at:string}|null;changes:Change[]}
const report = ref<Report|null>(null), error = ref(''), group = ref(''), kind = ref('all')
const controller = new AbortController()
onBeforeUnmount(()=>controller.abort())
onMounted(async()=>{try {const response=await fetch(`${import.meta.env.BASE_URL}data/changes.json`,{cache:'no-store',signal:controller.signal});if(!response.ok)throw new Error('Change history could not be loaded.');const value=await response.json();if(value.schema_version!==1||value.current?.sha!==props.data.source.sha256||!Array.isArray(value.changes))throw new Error('History and timetable do not match. Refresh after preparing the data.');report.value=value}catch(e){error.value=(e as Error).message}})
const changes = computed(()=>report.value?.changes.filter(c=>(kind.value==='all'||c.kind===kind.value)&&(!group.value||(c.after??c.before)?.group===group.value))??[])
const date=(value:string)=>new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Malta'}).format(new Date(value))
</script>
<template><section class="feature-page"><h1>What changed?</h1><p v-if="error" class="source-banner" role="alert">{{ error }}</p><p v-else-if="!report" role="status">Loading changes…</p><template v-else><p class="source-banner" v-if="report.baseline">Baseline recorded {{ date(report.current.imported_at) }}. Changes will appear after a different timetable PDF is imported. No earlier snapshot is available.</p><template v-else><p>Comparing {{ date(report.previous!.imported_at) }} → {{ date(report.current.imported_at) }} · Malta time</p><div class="feature-controls"><label>Group<select v-model="group"><option value="">All groups</option><option v-for="g in data.groups" :key="g.id" :value="g.id">{{ g.label }}</option></select></label><label>Change<select v-model="kind"><option value="all">All changes</option><option value="added">Added</option><option value="removed">Removed</option><option value="changed">Changed</option></select></label></div><h2>{{ changes.length }} {{ changes.length===1?'change':'changes' }}</h2><article v-for="(change,i) in changes" :key="i" class="change-card"><p class="change-summary">{{ change.kind }} <span v-if="change.fields.length">· {{ change.fields.join(', ') }}</span></p><h3>{{ (change.after??change.before)!.group }} · {{ (change.after??change.before)!.subject_name }}</h3><div class="change-versions"><div v-for="(entry,label) in {Before:change.before,After:change.after}" :key="label"><strong>{{ label }}</strong><template v-if="entry"><p>{{ entry.weekday }} · {{ entry.start }}–{{ entry.end }}</p><p>{{ entry.rooms.join(' · ')||'Room not printed' }} · {{ entry.subject_code||'Code not printed' }}</p></template><p v-else>{{ label==='Before'?'Not in previous import':'Not in latest import' }}</p></div></div></article><p v-if="!changes.length">No changes match this selection.</p><p class="availability-scope">Moves are paired only when a match is unambiguous. Other differences appear as additions and removals; a removal does not confirm a cancellation.</p></template></template></section></template>
